mapper.select:
SELECT ACM.* FROM `AI_CHAT_MESSAGE` ACM WHERE ACM.DELETED = 0
AND ACM.ENV_CODE = #{req.envCode}
AND ACM.MEMORY_KEY = #{req.memoryKey}
AND ACM.ROLE = #{req.role}
ORDER BY ACM.CREATE_TIME DESC

SELECT ACCOUNT_KEY AS accountKey, COUNT(1) AS callCount, COALESCE(SUM(PROMPT_TOKENS), 0) AS promptTokens, COALESCE(SUM(COMPLETION_TOKENS), 0) AS completionTokens, COALESCE(SUM(TOTAL_TOKENS), 0) AS totalTokens FROM `AI_CHAT_MESSAGE` WHERE DELETED = 0
AND ENV_CODE = #{envCode}
AND ACCOUNT_KEY IN
#{key}
GROUP BY ACCOUNT_KEY
